// Vercel serverless entrypoint - loads the compiled CommonJS backend
import { createRequire } from "node:module";
import path from "node:path";

// Load the compiled CommonJS backend (generated by `npm run build`)
const loadModule = createRequire(path.resolve(__dirname));
const { router } = loadModule("./dist/app.js") as { router: import("express").Router };

import express from "express";

const app = express();

app.use(express.json({ limit: "4mb" }));

// Mount the router at /api and /api-ruleta (same as local server.ts)
app.use("/api", router);
app.use("/api-ruleta", router);

// Health check for Vercel
app.get("/health", (_req, res) => {
  res.status(200).json({ status: "OK", timestamp: new Date().toISOString() });
});

export default app;